// TH15 synthetic bullet aliases (modern catalog reuse), only the two types used by
// st07bs.ecl BossCard8: etSprite type33 and EX SETSPRITE type19.
// Source: transcribe/th15/touhou-bullets.ecl; radii are the verified modern values.
const TH15_GLOW_BALL: int = 880;   // native type33, color1, r=12
const TH15_BIG_BALL2: int = 656;   // native type19, color3, r=8.5

// TH15 v1.00b Extra Stage 7 / BossCard8 (source st07bs.ecl.txt:2404-2469,
// dependency BossCard8_at 2471-2506). Rank 4 only; source difficulty mask is !LO -> O.
//
// Card-frame relation: the boss enemy is spawned by main at card frame 0 and its
// main task first runs at frame 1. spell_begin starts the segment clock there;
// the 120-frame opening buffer brings source entry t=0 to about card frame 121.
// Source timerReset is at t=4 (about card 125), the 4800-frame timeout therefore
// lands at about card 4925, and TIME_LIMIT=4924 ends the segment on that frame.
//
// Source mapping of this attack:
//   BossCard8 entry          -> boss_card8 (box/limit/HP entry state below)
//   BossCard8_at             -> fire_card8_volley
//   moveRand(30,4,2.0)       -> move_rand_card8 (per-tick moveLimit clamp)
//   floatTime(0,%D,...)      -> elapsed/c in the volley loop (exact linear ramp)
//   etEx ANIM a=1            -> baked into sh_dist 18 = 24 - 4*1.5
//   etEx WAIT90 + SETSPRITE  -> CARD8_SWAP xformdef
//
// The independent invulnerable shell keeps the real boss body/hurt box, movement,
// movement limit and firing; no player DPS advances the attack.

const TIME_LIMIT: int = 4924;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 116;
const BOSS_HP: int = 3000;       // inherited from Boss8 setInterrupt HP=3000
const BOSS_START_X: fx = 0fx;    // Boss() public entry state: movePos(0,128)
const BOSS_START_Y: fx = 128fx;
const BOSS_MOVE_Y: fx = 160fx;   // BossCard8 movePosTime(60,4,0,160)
const RING_WAYS: int = 61;       // etCount(...,61,1)
const BULLET_SPEED: fx = 1.5fx;  // etSpeed(...,1.5,0.2), M=1 uses 1.5

// Source etEx records on et1: ANIM(a=1), BRIGHT, WAIT(90), SETSPRITE(19,3),
// BRIGHT(0), LAYER(3). Only the delayed appearance change affects danger; BRIGHT
// and LAYER are visual. Source SETSPRITE re-reads the new type radius (8.5), the
// target op keeps the birth radius 12 (documented EX boundary, see report).
// The unused by-value parameter forces the shared dynamic xform program: in this
// harness build a bare zero-arg xform bound via sh_xform made sh_fire no-op with
// one contract_viol per volley, while the same sequence through NAME(0) runs.
xformdef CARD8_SWAP(unused: int) {
    @90 add_speed(0fx);
    set_sprite(TH15_BIG_BALL2, 3);
}

// One volley of BossCard8_at: two 61-way fixed rings (etAim mode3), same angle,
// et1 spawns 24-4*1.5=18px out, et0 spawns the full etDist 24px out.
sub setup_card8_shooters() {
    sh_reset(1);
    sh_sprite(1, TH15_GLOW_BALL, 1);
    sh_ring(1, 1);                 // etAim(1,3): fixed-direction full ring
    sh_aim(1, 0);
    sh_count(1, RING_WAYS, 1);
    sh_speed(1, BULLET_SPEED, 0fx);
    sh_dist(1, 18fx);              // etDist 24 - ANIM a=1 shift 4*1.5
    sh_xform(1, CARD8_SWAP(0));    // unused arg: dynamic program path (see xformdef)

    sh_reset(0);
    sh_sprite(0, TH15_GLOW_BALL, 1);
    sh_ring(0, 1);                 // etAim(0,3)
    sh_aim(0, 0);
    sh_count(0, RING_WAYS, 1);
    sh_speed(0, BULLET_SPEED, 0fx);
    sh_dist(0, 24fx);              // etDist(0,24), no EX on this ring
}

sub fire_card8_volley() {
    // %A = -pi/2 + RANDF2*0.17453292f; RANDF2 is -1..1, sampled once per volley.
    var r: int = rand(65536) - 32768;
    // 1820 BAM ~= 10deg; integer form of RANDF2*0.17453292, one sample per volley.
    var a: int = -16384 + (r * 1820) / 32768;
    // Source order: etAngle(1); etOn(1); etAngle(0); etOn(0).
    sh_angle(1, a as angle, 0deg);
    sh_fire(1);
    sh_angle(0, a as angle, 0deg);
    sh_fire(0);
}

// Source moveRand(30,4,2.0) at the current moveLimit(0,160,240,16).
// Approved TH16/TH18 moveRand recipe reused with N=30, speed=2.0 and this limit:
// direction sampled once, speed falls linearly 2*(1-k/30), every tick clamped to
// x in [-120,120], y in [152,168]. Inner direction zone is center +- width/4 and
// +- height/4, i.e. x in [-60,60], y in [156,164].
sub move_rand_card8() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 156fx {
        if a < 0 { a = -a; }
    } else if $self_y > 164fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad -> nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }

    var ang: angle = a as angle;
    var cx: fx = cos(ang);
    var cy: fx = sin(ang);
    for k in 1..31 {
        var speed: fx = 2fx * ((30 - k) as fx) / 30fx;
        var nx: fx = $self_x + cx * speed;
        var ny: fx = $self_y + cy * speed;
        if nx < -120fx { nx = -120fx; }
        if nx > 120fx { nx = 120fx; }
        if ny < 152fx { ny = 152fx; }
        if ny > 168fx { ny = 168fx; }
        // ECL writes the next movement tick; phase 5 performs it.
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
}

async sub boss_card8() {
    // Boss() entry state (st07bs.ecl.txt:8-39): hitbox 48 -> r24, hurtbox 40 -> r20,
    // initial position (0,128) supplied by spawn_enemy.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);

    // Original spellEx(116,4800,...) + setInterrupt timeout; segment clock starts here.
    spell_begin(0, SPELL_ID, none, TIME_LIMIT, 0, SPELL_SURVIVAL, 0);

    wait(OPENING_BUFFER);  // source entry t=0

    // t=0: $TIMEOUT==0 -> etCancel(640). No prior bullets in an independent card,
    // but keep the clear at the source position.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(2);               // t=2, setChapter(69) omitted (chapter state)
    wait(2);               // t=4

    // t=4: unknown569(1)/timerReset (timer is the segment clock above).
    // killAllAsync: this independent card has no async children. enmKillAll kept.
    kill_all_enemies(KILL_SILENT);
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // second $TIMEOUT==0 etCancel(640)
    // spellEnd/funcSet(0)/laserCancel/playSound: segment-external or pure presentation;
    // this card starts with no prior card, callback or laser.
    // moveVel/moveVelTime/movePosTime(0,0,0,0): clear movement, then the source
    // movePosTime(60,4,0,160) below.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(60, BOSS_START_X, BOSS_MOVE_Y, EASE_QUAD_OUT);

    setup_card8_shooters();
    wait(90);              // t=94: moveLimit(0,160,240,16) is implemented in move_rand_card8

    // floatTime(0,%D,3600,0,160,60): linear 160->60 over 3600 frames, then holds 60.
    // %F0=1.3 and $A are written but never read by BossCard8.
    var elapsed: int = 0;
    var e: int = 1000;     // $E loop guard; source timeout stops far earlier
    while e > 0 && spell_timer() >= 0 {
        fire_card8_volley();
        var c: int = 60;
        if elapsed < 3600 {
            // C = int(%D), truncation toward zero; exact integer form of 160-100*t/3600.
            c = (576000 - 100 * elapsed) / 3600;
        }
        wait(c);
        move_rand_card8(); // starts at t+c, 30 movement ticks
        wait(10);          // source wait(40) total after moveRand
        elapsed = elapsed + c + 40;
        e = e - 1;
    }
    loop { wait(1000); }
}

sub main() {
    _ = spawn_enemy(BOSS_START_X, BOSS_START_Y, BOSS_HP, 0, 0, 0, boss_card8);
    loop { wait(600); }
}
